"use client";

import { ArrowLeftIcon, FolderKanbanIcon, PencilIcon, PlusIcon, UserRoundIcon } from "lucide-react";
import { useRef } from "react";

import { ActionToastProvider } from "@/components/action-toast";
import { IconTooltip } from "@/components/icon-tooltip";
import { Link } from "@/components/link";
import { useLoadingActivity } from "@/components/loading-indicator";
import { CustomerForm } from "@/components/plugins/customers/customer-form";
import { customerLabels } from "@/components/plugins/customers/labels";
import type {
  CustomerDetailPageProps,
  CustomerNewPageProps,
  CustomerSection,
  CustomersPageProps,
} from "@/components/plugins/customers/types";
import {
  buttonClass,
  cardClass,
  CustomerActionButton,
  CustomerAvatar,
  CustomerStatusBadge,
  iconButtonClass,
  primaryButtonClass,
} from "@/components/plugins/customers/ui";
import { customerDisplayName } from "@/components/plugins/customers/utils";
import { RecordDeleteButton, useRecordDeletion } from "@/components/record-deletion";
import { TableSearch } from "@/components/table-search";
import {
  TableBulkDelete,
  TableSelectionCheckbox,
  useTableSelection,
} from "@/components/table-selection";
import { cn } from "@/components/utils/cn";
import {
  tableActionCellClass,
  tableActionHeaderClass,
  tableActionsClass,
  tableCellClass,
  tableClass,
  tableHeaderClass,
  tablePanelClass,
  tableRowClass,
} from "@/components/utils/table-styles";
import { useOptimisticAction } from "@/components/utils/use-optimistic-action";

export type {
  Customer,
  CustomerFormValues,
  CustomerCreateValues,
  CustomerSection,
  CustomersPageProps,
  CustomerDetailPageProps,
  CustomerNewPageProps,
} from "@/components/plugins/customers/types";
export type { CustomersLabels } from "@/components/plugins/customers/labels";

const pageClass = "mx-auto w-full min-w-0 space-y-6 px-4 py-8 text-foreground";

function CustomersPageContent({
  customers: suppliedCustomers,
  search,
  onSearchChange,
  loading = false,
  error: loadError,
  createHref,
  getCustomerHref,
  onDelete,
  onSetVerified,
  onImpersonate,
  toolbar,
  syncColumn,
  className,
  labels: overrides,
  linkComponent: CustomerLink = Link,
}: CustomersPageProps) {
  useLoadingActivity(loading);
  const labels = { ...customerLabels, ...overrides };
  const optimistic = useOptimisticAction(suppliedCustomers);
  const root = useRef<HTMLElement>(null);
  const deletion = useRecordDeletion({
    items: optimistic.value,
    scope: search,
    getName: customerDisplayName,
    onDelete,
    label: labels.deleteCustomer,
    labels,
    disabled: loading || !!loadError || optimistic.pending,
    returnFocus: root,
    className: "max-w-md",
  });
  const customers = deletion.items;
  const selectable = onDelete ? customers : [];
  const selection = useTableSelection(selectable, search ?? "");
  const selectionDisabled =
    loading || !!loadError || optimistic.pending || deletion.pending || selection.pending;
  const error = loadError || (optimistic.error ? labels.actionError : undefined);
  return (
    <div className={cn(pageClass, className)}>
      <section
        ref={root}
        tabIndex={-1}
        className={cn(tablePanelClass, "space-y-5 focus-visible:ring-2 focus-visible:ring-ring")}
        aria-label={labels.title}
      >
        <header className="flex flex-wrap items-center justify-between gap-3">
          <div className="space-y-1.5">
            <h1 className="text-base font-semibold">{labels.title}</h1>
            <p className="text-sm text-muted-foreground">{labels.description}</p>
          </div>
          <div className="ml-auto flex max-w-full flex-wrap items-center justify-end gap-2">
            <TableSearch
              value={search}
              onValueChange={onSearchChange}
              label={labels.search}
              placeholder={labels.searchPlaceholder}
              clearLabel={labels.clearSearch}
            />
            {toolbar}
            <CustomerLink href={createHref} className={primaryButtonClass}>
              <PlusIcon className="size-4 shrink-0" aria-hidden="true" />
              {labels.create}
            </CustomerLink>
          </div>
        </header>
        <div className="overflow-x-auto">
          <table className={tableClass} aria-busy={loading}>
            {loading && customers.length > 0 && (
              <caption className="sr-only">
                <output>{labels.loading}</output>
              </caption>
            )}
            <thead>
              <tr className={tableRowClass}>
                {onDelete && (
                  <th scope="col" className="w-10 p-2">
                    <TableSelectionCheckbox
                      label={labels.selectAllRows}
                      checked={selection.all}
                      mixed={selection.mixed}
                      onChange={selection.toggleAll}
                      disabled={selectionDisabled || !selectable.length}
                    />
                  </th>
                )}
                {[
                  labels.customer,
                  labels.email,
                  labels.status,
                  ...(syncColumn ? [syncColumn.label] : []),
                  labels.actions,
                ].map((label, index) => (
                  <th
                    scope="col"
                    key={index}
                    className={
                      index === (syncColumn ? 4 : 3) ? tableActionHeaderClass : tableHeaderClass
                    }
                  >
                    <div
                      className={
                        index === (syncColumn ? 4 : 3)
                          ? "flex items-center justify-end gap-2"
                          : undefined
                      }
                    >
                      {label}
                      {index === (syncColumn ? 4 : 3) && (
                        <>
                          {onDelete && (
                            <TableBulkDelete
                              selection={selection}
                              getName={customerDisplayName}
                              onDelete={(customer) => onDelete!(customer.id)}
                              labels={labels}
                              disabled={selectionDisabled}
                            />
                          )}
                        </>
                      )}
                    </div>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody className="[&_tr:last-child]:border-0">
              {customers.map((customer) => (
                <tr
                  key={customer.id}
                  hidden={selection.isDeleting(customer.id)}
                  className={tableRowClass}
                >
                  {onDelete && (
                    <td className="w-10 p-2">
                      <TableSelectionCheckbox
                        label={`${labels.selectRow}: ${customerDisplayName(customer)}`}
                        checked={selection.selected.some((row) => row.id === customer.id)}
                        mixed={false}
                        onChange={(checked) => selection.toggle(customer.id, checked)}
                        disabled={selectionDisabled}
                      />
                    </td>
                  )}
                  <td className={tableCellClass}>
                    <div className="flex items-center gap-3">
                      <CustomerAvatar customer={customer} />
                      <div className="space-y-0.5">
                        <CustomerLink
                          href={getCustomerHref(customer, "about")}
                          className="font-medium whitespace-nowrap hover:underline focus-visible:ring-2 focus-visible:ring-ring"
                        >
                          {customerDisplayName(customer)}
                        </CustomerLink>
                        {customer.companyName?.trim() && (
                          <p className="text-xs text-muted-foreground">{customer.name}</p>
                        )}
                      </div>
                    </div>
                  </td>
                  <td className={tableCellClass}>
                    <span className="whitespace-nowrap">{customer.email}</span>
                  </td>
                  <td className={tableCellClass}>
                    <CustomerStatusBadge
                      customer={customer}
                      labels={labels}
                      disabled={selectionDisabled}
                      onChange={
                        onSetVerified
                          ? (verified) =>
                              optimistic.run(
                                (rows) =>
                                  rows.map((row) =>
                                    row.id === customer.id
                                      ? { ...row, emailVerified: verified }
                                      : row,
                                  ),
                                () => onSetVerified(customer.id, verified),
                              )
                          : undefined
                      }
                    />
                  </td>
                  {syncColumn && <td className={tableCellClass}>{syncColumn.render(customer)}</td>}
                  <td className={tableActionCellClass}>
                    <div className={tableActionsClass}>
                      {onImpersonate && (
                        <CustomerActionButton
                          disabled={selectionDisabled}
                          label={labels.impersonate}
                          labels={labels}
                          onAction={() => onImpersonate(customer.id)}
                        >
                          <UserRoundIcon aria-hidden="true" />
                        </CustomerActionButton>
                      )}
                      <IconTooltip label={labels.viewProjects}>
                        <CustomerLink
                          href={getCustomerHref(customer, "projects")}
                          className={iconButtonClass}
                          aria-label={labels.viewProjects}
                        >
                          <FolderKanbanIcon aria-hidden="true" />
                        </CustomerLink>
                      </IconTooltip>
                      <IconTooltip label={labels.edit}>
                        <CustomerLink
                          href={getCustomerHref(customer, "about")}
                          className={iconButtonClass}
                          aria-label={labels.edit}
                        >
                          <PencilIcon className="size-4 shrink-0" aria-hidden="true" />
                        </CustomerLink>
                      </IconTooltip>
                      {onDelete && (
                        <RecordDeleteButton
                          label={labels.deleteCustomer}
                          disabled={selectionDisabled}
                          onClick={(event) => deletion.open(customer.id, event.currentTarget)}
                        />
                      )}
                    </div>
                  </td>
                </tr>
              ))}
              {((error && !loading) || customers.length === 0) && (
                <tr className={tableRowClass}>
                  <td
                    colSpan={(syncColumn ? 5 : 4) + (onDelete ? 1 : 0)}
                    className={cn(tableCellClass, "py-10 text-center text-muted-foreground")}
                  >
                    {error && !loading ? (
                      <p role="alert" className="text-destructive">
                        {error}
                      </p>
                    ) : (
                      <output>{loading ? labels.loading : labels.empty}</output>
                    )}
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </section>
      {deletion.dialog}
    </div>
  );
}

function CustomerDetailPageContent({
  customer: suppliedCustomer,
  section = "about",
  backHref,
  sectionHrefs,
  onSave,
  onDelete,
  onSetVerified,
  emailChangeDescription,
  projectsContent,
  syncContent,
  className,
  labels: overrides,
  linkComponent: CustomerLink = Link,
}: CustomerDetailPageProps) {
  const labels = { ...customerLabels, ...overrides };
  const optimistic = useOptimisticAction(suppliedCustomer, suppliedCustomer.id);
  const customer = optimistic.value;
  return (
    <div className={cn(pageClass, className)}>
      <CustomerLink
        href={backHref}
        className={cn(buttonClass, "hover:bg-primary/5 hover:text-primary")}
      >
        <ArrowLeftIcon aria-hidden="true" />
        {labels.back}
      </CustomerLink>
      <header className={cn(cardClass, "flex flex-wrap items-center gap-4")}>
        <div className="flex min-w-0 items-center gap-4">
          <CustomerAvatar customer={customer} large />
          <div className="min-w-0">
            <h1 className="truncate text-base font-semibold">{customerDisplayName(customer)}</h1>
            <p className="truncate text-sm text-muted-foreground">{customer.email}</p>
          </div>
        </div>
        <dl className="ml-auto flex flex-wrap justify-end gap-x-6 gap-y-2 self-start text-sm">
          <div>
            <dt className="sr-only">{labels.email}</dt>
            <dd className="mt-1">
              <CustomerStatusBadge
                customer={customer}
                labels={labels}
                disabled={optimistic.pending}
                onChange={
                  onSetVerified
                    ? (verified) =>
                        optimistic.run(
                          (row) => ({ ...row, emailVerified: verified }),
                          () => onSetVerified(customer.id, verified),
                        )
                    : undefined
                }
              />
            </dd>
          </div>
          {customer.banned && (
            <div>
              <dt className="text-muted-foreground">{labels.banned}</dt>
              <dd className="mt-1 inline-flex items-center gap-1.5 rounded-full bg-status-canceled px-2 py-0.5 text-xs font-medium text-status-canceled-foreground before:size-1.5 before:shrink-0 before:rounded-full before:bg-current">
                {labels.yes}
              </dd>
            </div>
          )}
        </dl>
      </header>
      <nav aria-label={labels.sections} className="flex overflow-x-auto border-b border-border">
        {(["about", "projects", "sync"] as const).map((tab: CustomerSection) => {
          const href = sectionHrefs[tab];
          if (!href) return null;
          return (
            <CustomerLink
              key={tab}
              href={href}
              aria-current={section === tab ? "page" : undefined}
              className={cn(
                "shrink-0 border-b-2 border-transparent px-4 py-2 text-sm font-semibold text-muted-foreground hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none focus-visible:ring-inset",
                section === tab && "border-primary text-primary",
              )}
            >
              {labels[tab]}
            </CustomerLink>
          );
        })}
      </nav>
      {section === "about" ? (
        <>
          <CustomerForm
            key={customer.id}
            customer={customer}
            labels={labels}
            onSubmit={(values) =>
              optimistic.run(
                (row) => ({
                  ...row,
                  ...values,
                  emailVerified: row.email === values.email && row.emailVerified,
                }),
                () => onSave(values),
              )
            }
            emailChangeDescription={emailChangeDescription}
            disabled={optimistic.pending}
            onDelete={
              onDelete
                ? (id) =>
                    optimistic.run(
                      (row) => row,
                      () => onDelete(id),
                    )
                : undefined
            }
          />
        </>
      ) : section === "projects" ? (
        projectsContent
      ) : (
        syncContent
      )}
    </div>
  );
}

export function CustomerNewPage({
  backHref,
  onCreate,

  className,
  labels: overrides,
  linkComponent: CustomerLink = Link,
}: CustomerNewPageProps) {
  const labels = { ...customerLabels, ...overrides };
  return (
    <div className={cn(pageClass, className)}>
      <CustomerLink
        href={backHref}
        className={cn(buttonClass, "hover:bg-primary/5 hover:text-primary")}
      >
        <ArrowLeftIcon aria-hidden="true" />
        {labels.back}
      </CustomerLink>
      <CustomerForm labels={labels} onSubmit={onCreate} />
    </div>
  );
}

export function CustomersPage(props: CustomersPageProps) {
  return (
    <ActionToastProvider>
      <CustomersPageContent {...props} />
    </ActionToastProvider>
  );
}

export function CustomerDetailPage(props: CustomerDetailPageProps) {
  return (
    <ActionToastProvider>
      <CustomerDetailPageContent key={props.customer.id} {...props} />
    </ActionToastProvider>
  );
}

"use client";

import { Input } from "@base-ui/react/input";
import { useId, useState, type FormEvent } from "react";

import { ActionToastProvider } from "@/components/action-toast";
import type { CustomersLabels } from "@/components/plugins/customers/labels";
import type {
  Customer,
  CustomerCreateValues,
  CustomerFormValues,
} from "@/components/plugins/customers/types";
import {
  cardClass,
  CustomerAvatar,
  Feedback,
  inputClass,
  primaryButtonClass,
  useCustomerAction,
} from "@/components/plugins/customers/ui";
import { customerDisplayName, customerFormValues } from "@/components/plugins/customers/utils";
import { RecordDeleteButton, useRecordDeletion } from "@/components/record-deletion";
import { cn } from "@/components/utils/cn";
import { editorActionsClass, useEditorValidation } from "@/components/utils/editor-form";

export interface CustomerFormProps {
  customer?: Customer;
  disabled?: boolean;
  labels: CustomersLabels;
  onSubmit: (values: CustomerCreateValues) => Promise<void>;
  onDelete?: (id: string) => Promise<void>;
  emailChangeDescription?: string;
}

function CustomerFormContent({
  customer,
  disabled,
  labels,
  onSubmit,
  onDelete,
  emailChangeDescription,
}: CustomerFormProps) {
  const id = `factory-customer-form-${useId()}`;
  const creating = !customer;
  const [values, setValues] = useState(() => customerFormValues(customer));
  const { formRef, issues: errors, setIssues: setErrors, clear } = useEditorValidation();
  const action = useCustomerAction(labels.actionError, customer?.id);
  const deletion = useRecordDeletion({
    items: customer ? [customer] : [],
    scope: customer?.id,
    getName: customerDisplayName,
    onDelete,
    label: labels.deleteCustomer,
    labels,
    disabled: disabled || action.pending,
    returnFocus: formRef,
    className: "max-w-md",
  });
  const pending = disabled || action.pending || deletion.pending;

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (pending) return;
    const form = event.currentTarget;
    const nextErrors: typeof errors = {};
    if (!values.name.trim()) nextErrors.name = labels.nameRequired;
    const emailInput = form.elements.namedItem("email") as HTMLInputElement;
    if (!values.email.trim() || emailInput.validity.typeMismatch)
      nextErrors.email = labels.emailRequired;
    setErrors(nextErrors);
    if (Object.keys(nextErrors).length) return;
    const normalized: CustomerFormValues = {
      ...values,
      name: values.name.trim(),
      email: values.email.trim(),
    };
    await action.run(
      () => onSubmit(normalized),
      creating ? labels.created : labels.saved,
      () => setValues(normalized),
    );
  }

  function field(
    name: keyof CustomerFormValues,
    options: {
      type?: string;
      autoComplete?: string;
      placeholder?: string;
      required?: boolean;
      full?: boolean;
      description?: string;
    } = {},
  ) {
    const error = errors[name];
    const descriptionId = `${id}-${name}-description`;
    const errorId = `${id}-${name}-error`;
    return (
      <div className={cn("space-y-2", options.full && "md:col-span-2")}>
        <label htmlFor={`${id}-${name}`} className="block text-sm font-semibold">
          {labels[name]}
          {options.required && " *"}
        </label>
        <Input
          id={`${id}-${name}`}
          name={name}
          type={options.type ?? "text"}
          autoComplete={options.autoComplete}
          placeholder={options.placeholder}
          required={options.required}
          value={values[name]}
          onChange={(event) => {
            setValues({ ...values, [name]: event.target.value });
            clear(name);
          }}
          className={inputClass}
          aria-invalid={Boolean(error)}
          aria-describedby={
            [options.description ? descriptionId : "", error ? errorId : ""]
              .filter(Boolean)
              .join(" ") || undefined
          }
        />
        {options.description && (
          <p id={descriptionId} className="text-sm text-muted-foreground">
            {options.description}
          </p>
        )}
        {error && (
          <p id={errorId} role="alert" className="text-sm text-destructive">
            {error}
          </p>
        )}
      </div>
    );
  }

  return (
    <form
      ref={formRef}
      tabIndex={-1}
      noValidate
      onSubmit={submit}
      aria-busy={pending}
      className="space-y-6 focus-visible:ring-2 focus-visible:ring-ring"
    >
      {creating && (
        <header className={cn(cardClass, "flex items-center gap-4")}>
          <CustomerAvatar customer={values} large />
          <div className="min-w-0 space-y-1.5">
            <h1 className="text-base font-semibold">{labels.newTitle}</h1>
            <p className="text-sm text-muted-foreground">{labels.newDescription}</p>
          </div>
        </header>
      )}
      <fieldset disabled={pending} className="min-w-0 space-y-6">
        <section aria-labelledby={`${id}-contact`} className={cn(cardClass, "space-y-5")}>
          <div className="space-y-1.5">
            <h2 id={`${id}-contact`} className="font-semibold">
              {labels.contactTitle}
            </h2>
            <p className="text-sm text-muted-foreground">{labels.contactDescription}</p>
          </div>
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            {field("name", { required: true, autoComplete: "name" })}
            {field("email", {
              type: "email",
              autoComplete: "email",
              required: true,
              description: creating ? undefined : emailChangeDescription,
            })}
            {field("phoneNumber", {
              type: "tel",
              autoComplete: "tel",
              placeholder: labels.phonePlaceholder,
            })}
          </div>
        </section>
        <section aria-labelledby={`${id}-company`} className={cn(cardClass, "space-y-5")}>
          <div className="space-y-1.5">
            <h2 id={`${id}-company`} className="font-semibold">
              {labels.companyTitle}
            </h2>
            <p className="text-sm text-muted-foreground">{labels.companyDescription}</p>
          </div>
          {field("companyName", { autoComplete: "organization" })}
        </section>
        <section aria-labelledby={`${id}-billing`} className={cn(cardClass, "space-y-5")}>
          <h2 id={`${id}-billing`} className="font-semibold">
            {labels.billingTitle}
          </h2>
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            {field("street", {
              full: true,
              autoComplete: "address-line1",
              placeholder: labels.streetPlaceholder,
            })}
            {field("city", { autoComplete: "address-level2", placeholder: labels.cityPlaceholder })}
            {field("addressComplement", {
              autoComplete: "address-line2",
              placeholder: labels.addressPlaceholder,
            })}
          </div>
        </section>
      </fieldset>
      <div className={editorActionsClass}>
        {customer && onDelete && (
          <RecordDeleteButton
            label={labels.deleteCustomer}
            disabled={pending}
            onClick={(event) => deletion.open(customer.id, event.currentTarget)}
          />
        )}
        <button type="submit" disabled={pending} className={cn(primaryButtonClass, "ml-auto")}>
          {pending ? labels.pending : creating ? labels.create : labels.save}
        </button>
      </div>
      <Feedback feedback={action.feedback} />
      {deletion.dialog}
    </form>
  );
}

export function CustomerForm(props: CustomerFormProps) {
  return (
    <ActionToastProvider>
      <CustomerFormContent {...props} />
    </ActionToastProvider>
  );
}

import type { ComponentType, ReactNode } from "react";

import type { LinkProps } from "@/components/link";
import type { CustomersLabels } from "@/components/plugins/customers/labels";

export type CustomerSection = "about" | "projects" | "sync";

export interface CustomerFormValues {
  name: string;
  email: string;
  phoneNumber: string;
  companyName: string;
  street: string;
  city: string;
  addressComplement: string;
}

export type CustomerCreateValues = CustomerFormValues;

export interface Customer extends Pick<CustomerFormValues, "name" | "email"> {
  id: string;
  emailVerified: boolean;
  image?: string | null;
  banned?: boolean | null;
  companyName?: string | null;
  phoneNumber?: string | null;
  street?: string | null;
  city?: string | null;
  addressComplement?: string | null;
}

export interface CustomersAppearanceProps {
  className?: string;
  labels?: Partial<CustomersLabels>;
  linkComponent?: ComponentType<LinkProps>;
}

export interface CustomersPageProps extends CustomersAppearanceProps {
  customers: readonly Customer[];
  search: string;
  onSearchChange: (search: string) => void;
  loading?: boolean;
  error?: string;
  createHref: string;
  getCustomerHref: (customer: Customer, section: CustomerSection) => string;
  onDelete?: (customerId: string) => Promise<void>;
  onSetVerified?: (customerId: string, verified: boolean) => Promise<void>;
  onImpersonate?: (customerId: string) => Promise<void>;
  toolbar?: ReactNode;
  syncColumn?: { label: string; render: (customer: Customer) => ReactNode };
}

export interface CustomerDetailPageProps extends CustomersAppearanceProps {
  customer: Customer;
  section?: CustomerSection;
  backHref: string;
  sectionHrefs: Record<Exclude<CustomerSection, "sync">, string> & { sync?: string };
  onSave: (values: CustomerFormValues) => Promise<void>;
  onDelete?: (customerId: string) => Promise<void>;
  onSetVerified?: (customerId: string, verified: boolean) => Promise<void>;
  emailChangeDescription?: string;
  projectsContent?: ReactNode;
  syncContent?: ReactNode;
}

export interface CustomerNewPageProps extends CustomersAppearanceProps {
  backHref: string;
  onCreate: (values: CustomerCreateValues) => Promise<void>;
}

"use client";

import { Avatar } from "@base-ui/react/avatar";
import { ChevronDownIcon } from "lucide-react";
import { useState, type ReactNode, type RefObject } from "react";

import { useActionToast } from "@/components/action-toast";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/dropdown-menu";
import { IconTooltip } from "@/components/icon-tooltip";
import type { CustomersLabels } from "@/components/plugins/customers/labels";
import type { Customer } from "@/components/plugins/customers/types";
import { customerDisplayName, customerInitials } from "@/components/plugins/customers/utils";
import { RecordDeleteButton, useRecordDeletion } from "@/components/record-deletion";
import { cn } from "@/components/utils/cn";
import { editorInvalidClass } from "@/components/utils/editor-form";
import { useMutationAction } from "@/components/utils/use-optimistic-action";

