export function useCustomerAction(errorMessage: string, scope?: unknown) {
  const notify = useActionToast();
  const mutation = useMutationAction(scope);
  return {
    pending: mutation.pending,
    feedback: mutation.error ? { error: true, message: errorMessage } : undefined,
    run: (action: () => Promise<void>, success: string, accept?: () => void) =>
      mutation.run(action, () => {
        notify(success);
        accept?.();
      }),
  };
}

export function Feedback({ feedback }: { feedback?: { error: boolean; message: string } }) {
  return feedback ? (
    <p
      role={feedback.error ? "alert" : "status"}
      className={cn("text-sm", feedback.error ? "text-destructive" : "text-muted-foreground")}
    >
      {feedback.message}
    </p>
  ) : null;
}

export function CustomerAvatar({
  customer,
  large = false,
}: {
  customer: Pick<Customer, "name" | "companyName" | "email" | "image">;
  large?: boolean;
}) {
  const name = customerDisplayName(customer);
  return (
    <Avatar.Root
      className={cn(
        "flex size-9 shrink-0 items-center justify-center overflow-hidden rounded-full border border-border",
        large && "size-16 text-xl",
      )}
    >
      <Avatar.Image
        src={customer.image ?? undefined}
        alt={name}
        className="size-full object-cover"
      />
      <Avatar.Fallback>{customerInitials(name, customer.email)}</Avatar.Fallback>
    </Avatar.Root>
  );
}

export function CustomerActionButton({
  label,
  onAction,
  labels,
  children,
  disabled = false,
}: {
  label: string;
  onAction: () => Promise<void>;
  labels: CustomersLabels;
  children: ReactNode;
  disabled?: boolean;
}) {
  const action = useCustomerAction(labels.actionError);
  return (
    <div>
      <IconTooltip label={label}>
        <button
          type="button"
          className={iconButtonClass}
          aria-label={label}
          disabled={disabled || action.pending}
          aria-busy={action.pending}
          onClick={() => void action.run(onAction, labels.actionSuccess)}
        >
          {children}
        </button>
      </IconTooltip>
      <Feedback feedback={action.feedback} />
    </div>
  );
}

export function DeleteCustomer({
  customer,
  onDelete,
  labels,
  disabled = false,
  returnFocus,
}: {
  customer: Customer;
  onDelete: (id: string) => Promise<void>;
  labels: CustomersLabels;
  disabled?: boolean;
  returnFocus?: RefObject<HTMLElement | null>;
}) {
  const deletion = useRecordDeletion({
    items: [customer],
    scope: customer.id,
    getName: customerDisplayName,
    onDelete,
    label: labels.deleteCustomer,
    labels,
    disabled,
    returnFocus,
    className: "max-w-md",
  });
  return (
    <>
      <RecordDeleteButton
        label={labels.deleteCustomer}
        disabled={disabled || deletion.pending}
        onClick={(event) => deletion.open(customer.id, event.currentTarget)}
      />
      {deletion.dialog}
    </>
  );
}

export interface StatusBadgeProps<T extends string> {
  value: T;
  options: readonly { value: T; label: string }[];
  label: string;
  className: string;
  disabled?: boolean;
  onChange?: (value: T) => Promise<void>;
  errorMessage: string;
  successMessage: string;
}

export function StatusBadge<T extends string>({
  value,
  options,
  label,
  className,
  disabled,
  onChange,
  errorMessage,
  successMessage,
}: StatusBadgeProps<T>) {
  const [open, setOpen] = useState(false);
  const action = useCustomerAction(errorMessage);
  const badgeClass = cn(
    "inline-flex shrink-0 items-center gap-1.5 rounded-full px-2 py-0.5 text-xs font-medium before:size-1.5 before:shrink-0 before:rounded-full before:bg-current",
    className,
  );
  const text = options.find((option) => option.value === value)?.label;
  if (!onChange) return <span className={badgeClass}>{text}</span>;
  return (
    <DropdownMenu
      open={open}
      onOpenChange={(next) => {
        if (!action.pending) setOpen(next);
      }}
    >
      <DropdownMenuTrigger
        aria-label={`${label}: ${text}`}
        disabled={disabled || action.pending}
        aria-busy={action.pending}
        className={cn(
          badgeClass,
          "min-h-10 outline-none hover:brightness-95 focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50 md:min-h-8",
        )}
      >
        {text}
        <ChevronDownIcon className="size-3 shrink-0" aria-hidden="true" />
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="end"
        className="w-max max-w-[calc(100vw-2rem)] min-w-48 rounded-xl"
      >
        <DropdownMenuRadioGroup
          value={value}
          aria-label={label}
          onValueChange={(next) => {
            const option = options.find((entry) => entry.value === next);
            if (!option || option.value === value || disabled || action.pending) return;
            void action.run(
              () => onChange(option.value),
              successMessage,
              () => setOpen(false),
            );
          }}
        >
          {options.map((option) => (
            <DropdownMenuRadioItem
              key={option.value}
              value={option.value}
              closeOnClick={false}
              disabled={disabled || action.pending}
              className="min-h-10 rounded-md md:min-h-8"
            >
              {option.label}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
        <div className="min-h-5 max-w-64 px-2" aria-busy={action.pending}>
          <Feedback feedback={action.feedback} />
        </div>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

export function CustomerStatusBadge({
  customer,
  labels,
  onChange,
  disabled,
}: {
  customer: Customer;
  labels: CustomersLabels;
  onChange?: (verified: boolean) => Promise<void>;
  disabled?: boolean;
}) {
  return (
    <StatusBadge
      value={customer.emailVerified ? "verified" : "unverified"}
      options={[
        { value: "verified", label: labels.verified },
        { value: "unverified", label: labels.unverified },
      ]}
      label={labels.verification(customerDisplayName(customer))}
      className={
        customer.emailVerified
          ? "bg-status-success text-status-success-foreground"
          : "bg-status-pending text-status-pending-foreground"
      }
      disabled={disabled}
      onChange={onChange ? (value) => onChange(value === "verified") : undefined}
      errorMessage={labels.actionError}
      successMessage={labels.saved}
    />
  );
}

import type { Customer, CustomerFormValues } from "@/components/plugins/customers/types";

export function customerDisplayName(customer: Pick<Customer, "name" | "companyName">) {
  return customer.companyName?.trim() || customer.name;
}

export function customerInitials(name: string, email: string) {
  return name.trim()
    ? name
        .trim()
        .split(/\s+/)
        .slice(0, 2)
        .map((part) => part[0])
        .join("")
        .toUpperCase()
    : email.trim().slice(0, 2).toUpperCase() || "?";
}

export function customerFormValues(customer?: Customer): CustomerFormValues {
  return {
    name: customer?.name ?? "",
    email: customer?.email ?? "",
    phoneNumber: customer?.phoneNumber ?? "",
    companyName: customer?.companyName ?? "",
    street: customer?.street ?? "",
    city: customer?.city ?? "",
    addressComplement: customer?.addressComplement ?? "",
  };
}
